import hashlib
import hmac
import json

from payhook.errors import InvalidNotification


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format.

    Two authentication paths are honored:

    * The current v1 path: ``X-Pay-Signature: v1=<hex>`` is HMAC-SHA256 over
      the ASCII timestamp, a single ``.`` byte, and the exact received body
      bytes.
    * The legacy r0 receipt path used by the deployed v0 connector:
      ``X-Pay-Receipt: r0=<hex>`` is HMAC-SHA256 over the ASCII timestamp, a
      single ``.``, and the UTF-8 ``event_id`` from the JSON object. This path
      is accepted when v1 is absent or does not match, since v0 deliveries may
      arrive with a reformatted body and no usable v1 digest.

    A matching authentication together with an in-window timestamp is
    sufficient. Any notification that cannot be accepted raises
    :class:`payhook.errors.InvalidNotification`.
    """
    # --- Timestamp: required, decimal, and within the accept window. ---
    stamp = _header(headers, "X-Pay-Timestamp")
    if stamp is None:
        raise InvalidNotification("missing timestamp")
    try:
        ts = int(stamp, 10)
    except (TypeError, ValueError):
        raise InvalidNotification("malformed timestamp")
    if abs(ts - now) > 300:
        raise InvalidNotification("stale timestamp")

    # --- Body: must be a UTF-8 JSON object with the required fields. ---
    if not isinstance(raw_body, (bytes, bytearray)):
        raise InvalidNotification("body must be bytes")
    body = bytes(raw_body)
    try:
        payload = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        raise InvalidNotification("malformed JSON")
    if not isinstance(payload, dict):
        raise InvalidNotification("payload is not a JSON object")

    event_id = _require_nonempty_str(payload.get("event_id"), "event_id")
    account_id = _require_nonempty_str(payload.get("account_id"), "account_id")
    amount_minor = _require_amount(payload.get("amount_minor"))
    currency = _require_currency(payload.get("currency"))

    # --- Authentication: current v1 body digest, then legacy r0 receipt. ---
    stamp_bytes = stamp.encode("ascii")

    if _v1_matches(headers, secret, stamp_bytes, body):
        authenticated = True
    else:
        authenticated = _r0_matches(headers, secret, stamp_bytes, event_id)

    if not authenticated:
        raise InvalidNotification("no valid signature or receipt")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }


def _header(headers, name):
    if headers is None:
        return None
    value = headers.get(name)
    if value is None:
        lowered = name.lower()
        for key, candidate in headers.items():
            if isinstance(key, str) and key.lower() == lowered:
                return candidate
    return value


def _tagged_digest(header_value, tag):
    """Return the hex digest for ``tag=<hex>``, or ``None`` if not present."""
    if not isinstance(header_value, str):
        return None
    prefix = tag + "="
    if not header_value.startswith(prefix):
        return None
    return header_value[len(prefix):]


def _v1_matches(headers, secret, stamp_bytes, body):
    digest = _tagged_digest(_header(headers, "X-Pay-Signature"), "v1")
    if digest is None:
        return False
    expected = hmac.new(secret, stamp_bytes + b"." + body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, digest)


def _r0_matches(headers, secret, stamp_bytes, event_id):
    digest = _tagged_digest(_header(headers, "X-Pay-Receipt"), "r0")
    if digest is None:
        return False
    message = stamp_bytes + b"." + event_id.encode("utf-8")
    expected = hmac.new(secret, message, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, digest)


def _require_nonempty_str(value, field):
    if not isinstance(value, str) or value == "":
        raise InvalidNotification("invalid %s" % field)
    return value


def _require_amount(value):
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise InvalidNotification("invalid amount_minor")
    return value


def _require_currency(value):
    if (
        not isinstance(value, str)
        or len(value) != 3
        or not value.isascii()
        or not value.isupper()
        or not value.isalpha()
    ):
        raise InvalidNotification("invalid currency")
    return value
